const updateUnitGroup = `-- name: UpdateUnitGroup :execresult
UPDATE unit_group SET
    name = COALESCE(?, name),
    notes = CASE WHEN ? = true THEN ? ELSE notes END,
    base_unit_id = COALESCE(?, base_unit_id),
    updated_at = NOW(3)
WHERE id = ?
AND account_id = ?
`

type UpdateUnitGroupParams struct {
	Name        sql.NullString
	UpdateNotes interface{}
	Notes       sql.NullString
	BaseUnitID  sql.NullString
	ID          string
	AccountID   sql.NullString
}

